mapper.select:

left join outbound_order oo on ood.outbound_order_id = oo.outbound_order_id

    ood.material_id = #{materialId}

        and date(ood.outbound_time) >= #{startDate}


        and date(ood.outbound_time) <= #{endDate}


order by ood.outbound_time desc

select * from outbound_order_detail
where material_batch_id = #{materialBatchId}
order by outbound_time desc

select
    sum(ood.quantity) as total_quantity,
    count(distinct ood.outbound_order_id) as order_count
from outbound_order_detail ood
left join outbound_order oo on ood.outbound_order_id = oo.outbound_order_id

    ood.material_id = #{materialId}
    and oo.outbound_status = 'completed'

        and oo.warehouse_id = #{warehouseId}


        and date(ood.outbound_time) >= #{startDate}


        and date(ood.outbound_time) <= #{endDate}
